(() => {
'use strict';
const C={g:'#c7f36b',c:'#79dce8',o:'#ffab78',r:'#ff808d',m:'#92a1ae'};
const fmt=(v,n=3)=>Number(v).toFixed(n), clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const H=p=>p<=0||p>=1?0:-p*Math.log(p)-(1-p)*Math.log(1-p);
const KL=(p,q)=> (p===0?0:p*Math.log(p/q))+(p===1?0:(1-p)*Math.log((1-p)/(1-q)));
const gauss=(x,m,s)=>Math.exp(-.5*((x-m)/s)**2)/(s*Math.sqrt(2*Math.PI));
function range(id,label,min,max,value,step=.01){return `<label class="range-control"><span>${label}<output id="${id}-v">${value}</output></span><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${value}"></label>`}
function stat(label,value,color=C.c){return `<div class="viz-stat"><span>${label}</span><strong style="color:${color}">${value}</strong></div>`}
function svg(inner,label){return `<svg viewBox="0 0 600 300" role="img" aria-label="${label}">${inner}</svg>`}
function grid(xmin=-3,xmax=3,ymin=-1,ymax=3){const X=x=>45+(x-xmin)/(xmax-xmin)*520,Y=y=>255-(y-ymin)/(ymax-ymin)*220;let str='';for(let x=Math.ceil(xmin);x<=xmax;x++)str+=`<path d="M${X(x)} 25V255" stroke="#293844" stroke-width=".7"/><text x="${X(x)}" y="275" text-anchor="middle" fill="${C.m}" font-size="11">${x}</text>`;for(let y=Math.ceil(ymin);y<=ymax;y++)str+=`<path d="M45 ${Y(y)}H565" stroke="#293844" stroke-width=".7"/><text x="32" y="${Y(y)+4}" text-anchor="end" fill="${C.m}" font-size="11">${y}</text>`;if(xmin<=0&&xmax>=0)str+=`<path d="M${X(0)} 25V255" stroke="#6b7c88"/>`;if(ymin<=0&&ymax>=0)str+=`<path d="M45 ${Y(0)}H565" stroke="#6b7c88"/>`;return {str,X,Y};}
function path(fn,g,min,max,color=C.c){let d='';for(let i=0;i<=220;i++){const x=min+(max-min)*i/220,y=fn(x);if(Number.isFinite(y))d+=`${d?'L':'M'}${g.X(x).toFixed(2)},${g.Y(y).toFixed(2)}`;}return `<path d="${d}" fill="none" stroke="${color}" stroke-width="2.5"/>`;}
const line=(x1,y1,x2,y2,c=C.g,dash='')=>`<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="${c}" stroke-width="2" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
const dot=(x,y,c=C.g,r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
function mount(root,body,update){root.innerHTML=body;root.querySelectorAll('input[type=range]').forEach(i=>i.addEventListener('input',()=>{root.querySelector(`#${i.id}-v`).textContent=i.value;update()}));update();}
function template(controls,instruction){return `<div class="viz-stage"></div><div class="viz-stats"></div><div class="viz-controls">${controls}</div><p class="viz-instruction">${instruction}</p>`;}
function paint(root,picture,stats){root.querySelector('.viz-stage').innerHTML=picture;root.querySelector('.viz-stats').innerHTML=stats;}
const defs={
function:{name:'Funciones y transformaciones',world:'foundations',question:'¿Qué hace cada parámetro a la geometría?',mount(root){let mode='quadratic';const body=template(`<div class="segmented"><button data-mode="quadratic" class="active">Cuadrática</button><button data-mode="exp">Exponencial</button><button data-mode="log">Logaritmo</button></div>${range('fa','a · escala',.2,2,1,.05)}${range('fb','b · traslación',-2,2,0,.05)}`,'Compara y = a·f(x−b). Cambiar a estira verticalmente; cambiar b traslada horizontalmente. El logaritmo solo existe para x > b.');function update(){const a=+root.querySelector('#fa').value,b=+root.querySelector('#fb').value,g=grid(-3,3,-1,6);const fn=x=>mode==='quadratic'?a*(x-b)**2:mode==='exp'?a*Math.exp(x-b):a*Math.log(x-b);const min=mode==='log'?Math.max(-3,b+.035):-3;paint(root,svg(`<defs><clipPath id="fclip"><rect x="45" y="25" width="520" height="230"/></clipPath></defs>${g.str}<g clip-path="url(#fclip)">${path(fn,g,min,3)}</g>`, 'Transformación de una función'),stat('FUNCIÓN',mode==='quadratic'?`${fmt(a,2)}(x − ${fmt(b,2)})²`:mode==='exp'?`${fmt(a,2)} exp(x − ${fmt(b,2)})`:`${fmt(a,2)} ln(x − ${fmt(b,2)})`)+stat('DOMINIO',mode==='log'?`x > ${fmt(b,2)}`:'ℝ',C.g));}mount(root,body,update);root.querySelectorAll('[data-mode]').forEach(btn=>btn.onclick=()=>{mode=btn.dataset.mode;root.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b===btn));update()});}},
derivative:{name:'De secante a tangente',world:'differential',question:'¿Qué queda cuando la distancia tiende a cero?',mount(root){mount(root,template(`${range('dx','x · punto',-1.5,1.5,.5,.05)}${range('dh','h · separación',.01,1.3,.8,.01)}`,'La curva es f(x)=x². La secante calcula una tasa entre dos puntos; al reducir h converge a la tangente. Predice la pendiente antes de mover x.'),()=>{const x=+root.querySelector('#dx').value,h=+root.querySelector('#dh').value,g=grid(-2,3,-1,6),slope=2*x+h;paint(root,svg(`${g.str}${path(t=>t*t,g,-2,2.5)}${path(t=>x*x+slope*(t-x),g,-2,3,C.o)}${path(t=>x*x+2*x*(t-x),g,-2,3,C.g)}${line(g.X(x),g.Y(x*x),g.X(x+h),g.Y((x+h)**2),C.o)}${dot(g.X(x),g.Y(x*x))}${dot(g.X(x+h),g.Y((x+h)**2),C.o)}`, 'Secante naranja y tangente verde a x al cuadrado'),stat('SECANTE',fmt(slope),C.o)+stat('TANGENTE · 2x',fmt(2*x),C.g)+stat('ERROR',fmt(h)));});}},
integral:{name:'Área y suma de Riemann',world:'integral',question:'¿Cómo emerge una integral desde una suma?',mount(root){mount(root,template(`${range('in','n · rectángulos',2,100,8,1)}${range('ib','b · límite superior',.2,2,1.5,.05)}`,'Integramos x² entre 0 y b. Cada rectángulo usa su extremo derecho: la aproximación sobreestima una función creciente. El área exacta es b³/3.'),()=>{const n=+root.querySelector('#in').value,b=+root.querySelector('#ib').value,g=grid(0,2.2,0,4.5),dx=b/n;let rects='',sum=0;for(let i=1;i<=n;i++){const y=(i*dx)**2;sum+=y*dx;rects+=`<rect x="${g.X((i-1)*dx)}" y="${g.Y(y)}" width="${g.X(dx)-g.X(0)}" height="${g.Y(0)-g.Y(y)}" fill="#79dce822" stroke="#79dce8" stroke-width=".5"/>`;}const exact=b**3/3;paint(root,svg(`${g.str}${rects}${path(x=>x*x,g,0,2,C.g)}`, 'Aproximación integral mediante rectángulos'),stat('SUMA',fmt(sum))+stat('INTEGRAL',fmt(exact),C.g)+stat('ERROR',fmt(sum-exact),C.o));});}},
matrix:{name:'Matrices como transformaciones',world:'linear',question:'¿Qué le hace una matriz al espacio?',mount(root){mount(root,template(`${range('ma','a',-2,2,1,.1)}${range('mb','b',-2,2,.6,.1)}${range('mc','c',-2,2,0,.1)}${range('md','d',-2,2,1,.1)}`,'Las columnas son los destinos de los vectores base. El determinante mide el factor de área con orientación. Si es cero, el plano colapsa en una recta o un punto.'),()=>{const a=+root.querySelector('#ma').value,b=+root.querySelector('#mb').value,c=+root.querySelector('#mc').value,d=+root.querySelector('#md').value,g=grid(-4,4,-3,3),T=(x,y)=>[a*x+b*y,c*x+d*y];let lines='';for(let i=-4;i<=4;i++){let p=T(i,-3),q=T(i,3);lines+=line(g.X(p[0]),g.Y(p[1]),g.X(q[0]),g.Y(q[1]),'#385c67');p=T(-4,i);q=T(4,i);lines+=line(g.X(p[0]),g.Y(p[1]),g.X(q[0]),g.Y(q[1]),'#385c67');}const corners=[[0,0],T(1,0),T(1,1),T(0,1)].map(p=>`${g.X(p[0])},${g.Y(p[1])}`).join(' ');paint(root,svg(`<defs><clipPath id="mclip"><rect x="45" y="25" width="520" height="230"/></clipPath></defs>${g.str}<g clip-path="url(#mclip)">${lines}<polygon points="${corners}" fill="#c7f36b22" stroke="${C.g}"/>${line(g.X(0),g.Y(0),g.X(a),g.Y(c),C.g)}${line(g.X(0),g.Y(0),g.X(b),g.Y(d),C.o)}${dot(g.X(a),g.Y(c),C.g)}${dot(g.X(b),g.Y(d),C.o)}</g>`, 'Cuadrícula transformada por matriz de dos dimensiones'),stat('MATRIZ',`[${fmt(a,1)} ${fmt(b,1)}; ${fmt(c,1)} ${fmt(d,1)}]`)+stat('DETERMINANTE',fmt(a*d-b*c),C.g)+stat('INVERTIBLE',Math.abs(a*d-b*c)<1e-8?'NO':'SÍ',C.o));});}},
bayes:{name:'El motor de Bayes',world:'bayesian',question:'¿Cuánta evidencia hace falta para cambiar una creencia?',mount(root){mount(root,template(`${range('bp','Prior · P(H)',.01,.99,.2,.01)}${range('bt','Sensibilidad · P(+|H)',.01,.99,.9,.01)}${range('bf','Falso positivo · P(+|¬H)',.01,.99,.1,.01)}`,'Observas un resultado positivo. Las probabilidades conjuntas son prior × verosimilitud. La evidencia normaliza. Una prueba precisa puede seguir dando un posterior modesto si el prior es muy bajo.'),()=>{const p=+root.querySelector('#bp').value,t=+root.querySelector('#bt').value,f=+root.querySelector('#bf').value,e=p*t+(1-p)*f,post=p*t/e;const bar=(y,label,v,color)=>`<text x="40" y="${y-12}" fill="${C.m}" font-size="14">${label}</text><rect x="40" y="${y}" width="520" height="20" fill="#25333d"/><rect x="40" y="${y}" width="${520*v}" height="20" fill="${color}"/><text x="40" y="${y+42}" fill="${color}" font-size="13">${fmt(v*100,1)}%</text>`;paint(root,svg(`${bar(50,'P(H) · antes',p,C.m)}${bar(150,'P(H | +) · después',post,C.g)}`, 'Cambio del prior al posterior tras evidencia positiva'),stat('CONJUNTA · H,+',fmt(p*t))+stat('EVIDENCIA · P(+)',fmt(e),C.o)+stat('POSTERIOR',fmt(post),C.g));});}},
distribution:{name:'Gaussiana, variabilidad y precisión',world:'statistics',question:'¿Qué significa estar seguro de una estimación?',mount(root){mount(root,template(`${range('gm','μ · media',-2,2,0,.05)}${range('gs','σ · desviación',.25,2,1,.05)}`,'El área total es siempre 1. Reducir σ concentra la masa y aumenta la altura. La precisión es 1/σ²: certeza del modelo, no garantía de verdad.'),()=>{const m=+root.querySelector('#gm').value,s=+root.querySelector('#gs').value,g=grid(-5,5,0,1.7);paint(root,svg(`${g.str}<path d="M${g.X(m-s)} ${g.Y(0)}V${g.Y(gauss(m-s,m,s))}" stroke="${C.o}" stroke-dasharray="3 4"/><path d="M${g.X(m+s)} ${g.Y(0)}V${g.Y(gauss(m+s,m,s))}" stroke="${C.o}" stroke-dasharray="3 4"/>${path(x=>gauss(x,m,s),g,-5,5)}${line(g.X(m),g.Y(0),g.X(m),g.Y(gauss(m,m,s)),C.g)}`, 'Densidad gaussiana y media'),stat('VARIANZA · σ²',fmt(s*s))+stat('PRECISIÓN · Π',fmt(1/(s*s)),C.g)+stat('MASA · μ±σ','68.27%',C.o));});}},
gradient:{name:'Seguir el gradiente',world:'multivariate',question:'¿Por qué una actualización pequeña puede acercarte al mínimo?',mount(root){let trace=[];root.innerHTML=template(`${range('gx','x · posición',-3,3,2.3,'any')}${range('gy','y · posición',-3,3,1.8,'any')}${range('gl','η · paso',.02,.65,.15,.01)}<button class="btn primary" id="gstep">Dar un paso</button><button class="btn" id="greset">Borrar trayectoria</button>`,'E(x,y)=x²+2y². Su gradiente es (2x,4y). Restarlo reduce E con 0<η<0.5; un paso excesivo puede divergir. Mueve el punto y observa el vector local.');const update=()=>{const x=+root.querySelector('#gx').value,y=+root.querySelector('#gy').value,g=grid(-3.2,3.2,-3.2,3.2);let contours='';for(let v=.5;v<=16;v*=1.7)contours+=`<ellipse cx="${g.X(0)}" cy="${g.Y(0)}" rx="${Math.sqrt(v)*520/6.4}" ry="${Math.sqrt(v/2)*220/6.4}" fill="none" stroke="#34505a"/>`;root.dataset.steps=String(Math.max(0,trace.length-1));const trail=trace.map(p=>`${g.X(p[0])},${g.Y(p[1])}`).join(' ');paint(root,svg(`${g.str}${contours}<polyline points="${trail}" fill="none" stroke="${C.o}" stroke-width="2"/>${line(g.X(x),g.Y(y),g.X(x-.22*2*x),g.Y(y-.22*4*y),C.g)}${dot(g.X(x),g.Y(y))}${dot(g.X(0),g.Y(0),C.c,3)}`, 'Contornos de energía y trayectoria de descenso'),stat('ENERGÍA',fmt(x*x+2*y*y),C.g)+stat('∇E',`(${fmt(2*x,2)}, ${fmt(4*y,2)})`)+stat('PASOS',trace.length?trace.length-1:0,C.o));};root.querySelectorAll('input').forEach(i=>i.oninput=()=>{root.querySelector(`#${i.id}-v`).textContent=i.value;trace=[];update()});root.querySelector('#gstep').onclick=()=>{const x=+root.querySelector('#gx').value,y=+root.querySelector('#gy').value,l=+root.querySelector('#gl').value;const nx=x*(1-2*l),ny=y*(1-4*l);if(Math.abs(nx)>3||Math.abs(ny)>3){root.querySelector('.viz-instruction').textContent='El paso saldría del dominio visible: elige η < 0.5 o una posición más cercana. La divergencia es una propiedad del algoritmo.';return;}if(!trace.length)trace.push([x,y]);trace.push([nx,ny]);[['gx',nx],['gy',ny]].forEach(([id,v])=>{root.querySelector('#'+id).value=v;root.querySelector('#'+id+'-v').textContent=fmt(v,2)});update()};root.querySelector('#greset').onclick=()=>{trace=[];update()};update();}},
entropy:{name:'Entropía y divergencia',world:'information',question:'¿Incertidumbre y discrepancia son lo mismo?',mount(root){mount(root,template(`${range('hp','p · Bernoulli real',.01,.99,.5,.01)}${range('hq','q · modelo',.01,.99,.7,.01)}`,'H(p) mide incertidumbre. KL(p∥q) mide el costo medio extra de describir p usando q. Es dirigida: invertir p y q cambia el resultado. Logaritmos naturales → nats.'),()=>{const p=+root.querySelector('#hp').value,q=+root.querySelector('#hq').value,g=grid(0,1,0,.75),cross=H(p)+KL(p,q);paint(root,svg(`${g.str}${path(H,g,.001,.999)}${dot(g.X(p),g.Y(H(p)),C.g)}${line(g.X(p),g.Y(0),g.X(p),g.Y(H(p)),C.g)}<text x="330" y="42" fill="${C.c}" font-size="14">H(p) · máximo en 1/2</text>`, 'Entropía de una distribución Bernoulli'),stat('H(p)',fmt(H(p)),C.g)+stat('KL(p∥q)',fmt(KL(p,q)),C.o)+stat('ENTROPÍA CRUZADA',fmt(cross))+stat('KL(q∥p)',fmt(KL(q,p)),C.o));});}},
dynamics:{name:'Atractores y ruido',world:'dynamics',question:'¿Puede fluctuar un sistema y seguir siendo estable?',mount(root){let seed=73;const random=()=>{seed=(1664525*seed+1013904223)>>>0;return(seed+.5)/4294967296};mount(root,template(`${range('dk','k · fuerza restauradora',-.6,2,.7,.05)}${range('dn','σ · ruido',0,1,.2,.05)}${range('d0','x₀ · inicio',-2,2,1.5,.05)}`,'dx=−k·x·dt+σ·dW. Usamos Euler–Maruyama, dt=0.04. k>0 restaura hacia 0; k<0 amplifica desviaciones. La varianza estacionaria σ²/(2k) exige k>0. La semilla fija permite comparar cambios.'),()=>{seed=73;const k=+root.querySelector('#dk').value,n=+root.querySelector('#dn').value,x0=+root.querySelector('#d0').value,g=grid(0,8,-3,3);let x=x0,pts=`${g.X(0)},${g.Y(x)}`;for(let i=1;i<=200;i++){const z=Math.sqrt(-2*Math.log(random()))*Math.cos(2*Math.PI*random());x+=-k*x*.04+n*.2*z;pts+=` ${g.X(i*.04)},${g.Y(x)}`;}paint(root,svg(`<defs><clipPath id="dclip"><rect x="45" y="25" width="520" height="230"/></clipPath></defs>${g.str}<g clip-path="url(#dclip)"><polyline points="${pts}" fill="none" stroke="${C.c}" stroke-width="2"/>${path(t=>x0*Math.exp(-k*t),g,0,8,C.g)}</g>`, 'Trayectoria estocástica y media determinista de Ornstein Uhlenbeck'),stat('E[x(8)]',fmt(x0*Math.exp(-k*8)),C.g)+stat('VAR. ESTACIONARIA',k>0?fmt(n*n/(2*k)):'no existe',C.o)+stat('ESTABILIDAD',k>0?'atractor':k<0?'repulsor':'sin restauración'));});}},
variational:{name:'Aproximar un posterior',world:'variational',question:'¿Por qué minimizar F acerca q al posterior?',mount(root){mount(root,template(`${range('vm','μq · media',-2,2,-1,.05)}${range('vs','σq · dispersión',.2,2,1.4,.05)}`,'El posterior objetivo es N(0.6,0.7²); q=N(μq,σq²). F=KL(q∥posterior)−ln p(o), con p(o)=0.2. Mueve q hasta hacerlo coincidir: la cota se vuelve exacta.'),()=>{const m=+root.querySelector('#vm').value,s=+root.querySelector('#vs').value,kl=Math.log(.7/s)+(s*s+(m-.6)**2)/(2*.49)-.5,g=grid(-4,4,0,2.1);paint(root,svg(`${g.str}${path(x=>gauss(x,.6,.7),g,-4,4,C.g)}${path(x=>gauss(x,m,s),g,-4,4,C.c)}<text x="55" y="42" fill="${C.g}" font-size="13">posterior</text><text x="155" y="42" fill="${C.c}" font-size="13">q</text>`, 'Aproximación gaussiana q y posterior objetivo'),stat('KL',fmt(Math.max(0,kl)),C.c)+stat('SORPRESA',fmt(-Math.log(.2)),C.o)+stat('F',fmt(kl-Math.log(.2)),C.g)+stat('ELBO',fmt(Math.log(.2)-kl),C.o));});}},
markov:{name:'Estados ocultos y mensajes',world:'generative',question:'¿Cómo se mueve una creencia en el tiempo?',mount(root){let t=0,observations=0,belief=.8;root.innerHTML=template(`${range('ka','α · P(R|L)',.01,.99,.15,.01)}${range('kb','β · P(L|R)',.01,.99,.35,.01)}<button class="btn primary" id="kstep">Predecir un paso</button><button class="btn" id="kobs">Observar señal L</button><button class="btn" id="kreset">Reiniciar</button>`,'B=[[1−α, β],[α,1−β]], estados [L,R]. Primero predices s′=B·s. Una señal L con fiabilidad 0.8 actualiza por Bayes. La distribución estacionaria es [β,α]/(α+β).');const update=()=>{root.dataset.belief=String(belief);root.dataset.predictions=String(t);root.dataset.observations=String(observations);const a=+root.querySelector('#ka').value,b=+root.querySelector('#kb').value;const bars=(x,p,label,color)=>`<rect x="${x}" y="${250-180*p}" width="130" height="${180*p}" fill="${color}" opacity=".85"/><text x="${x+65}" y="275" text-anchor="middle" fill="${color}" font-size="16">${label} · ${fmt(p)}</text>`;paint(root,svg(`${line(50,250,550,250,C.m)}${bars(120,belief,'L',C.g)}${bars(350,1-belief,'R',C.c)}`, 'Creencia categórica sobre dos estados'),stat('PASO',t)+stat('ESTACIONARIA · L',fmt(b/(a+b)),C.g)+stat('SUMA COLUMNAS B','1, 1',C.o));};root.querySelectorAll('input').forEach(i=>i.oninput=()=>{root.querySelector(`#${i.id}-v`).textContent=i.value;update()});root.querySelector('#kstep').onclick=()=>{const a=+root.querySelector('#ka').value,b=+root.querySelector('#kb').value;belief=(1-a)*belief+b*(1-belief);t++;update()};root.querySelector('#kobs').onclick=()=>{observations++;belief=.8*belief/(.8*belief+.2*(1-belief));update()};root.querySelector('#kreset').onclick=()=>{t=0;observations=0;belief=.8;update()};update();}},
policy:{name:'Valor pragmático y epistémico',world:'decision',question:'¿Cuál política reduce mejor la energía libre esperada?',mount(root){mount(root,template(`${range('pp','p · creencia estado L',.01,.99,.5,.01)}${range('pc','c · preferencia por resultado L',.05,.95,.75,.01)}${range('pr','r · fiabilidad de explorar',.5,.99,.9,.01)}`,'Compara dos canales: explorar revela el estado con fiabilidad r; el canal opaco produce L/R con probabilidad 1/2, independiente del estado. Convención explícita: preferencias sobre observaciones. G=riesgo+ambigüedad=−información−E[ln P_C(o)]. Se omite F(π) pasado e igual prior de políticas.'),()=>{const p=+root.querySelector('#pp').value,c=+root.querySelector('#pc').value,r=+root.querySelector('#pr').value,e=p*r+(1-p)*(1-r),ig=H(e)-H(r),g1=KL(e,c)+H(r),g2=KL(.5,c)+H(.5),prob=1/(1+Math.exp(g1-g2));const row=(y,name,G,risk,amb,color)=>`<text x="35" y="${y}" fill="${color}" font-size="15">${name}</text><rect x="35" y="${y+15}" width="${Math.min(515,risk*130)}" height="24" fill="${C.o}"/><rect x="${35+Math.min(515,risk*130)}" y="${y+15}" width="${Math.min(515-Math.min(515,risk*130),amb*130)}" height="24" fill="${C.c}"/><text x="35" y="${y+62}" fill="${C.m}" font-size="13">G=${fmt(G)} · riesgo ${fmt(risk)} + ambigüedad ${fmt(amb)}</text>`;paint(root,svg(`${row(42,'EXPLORAR',g1,KL(e,c),H(r),C.g)}${row(175,'CANAL OPACO',g2,KL(.5,c),H(.5),C.m)}`, 'Comparación de energía libre esperada por política'),stat('IG · EXPLORAR',fmt(ig),C.g)+stat('IG · OPACO','0.000',C.o)+stat('q(EXPLORAR)',fmt(prob),C.c));});}},
agent:{name:'Agente en un mundo oculto',world:'active',question:'¿Actúas ya o compras información?',mount(root){let episode=1,hidden=Math.random()<.5?'L':'R',belief=.5,signals=0,ended=false,log=[],reward=0;const reset=()=>{episode++;hidden=Math.random()<.5?'L':'R';belief=.5;signals=0;ended=false;log=[];render()};root.innerHTML=`<div class="agent-world"></div><div class="viz-stats"></div><div class="agent-actions"><button class="btn" data-action="sense">Escanear · costo 0.1</button><button class="btn primary" data-action="L">Elegir L</button><button class="btn primary" data-action="R">Elegir R</button><button class="btn" id="anext">Nuevo episodio</button></div><div class="agent-log" aria-live="polite"></div><p class="viz-instruction">Un recurso está oculto en L o R, con prior 1/2. El sensor acierta con probabilidad 0.85; cada lectura cuesta 0.1. Elegir el lado correcto da +1 y termina el episodio; fallar da 0. Las lecturas son condicionalmente independientes. Demuestra la diferencia entre actuar y reducir incertidumbre.</p>`;function render(){root.dataset.agentSolved=String(ended&&log.length>0&&((hidden==='L'&&belief>=.85)||(hidden==='R'&&belief<=.15))&&signals>0&&signals<=3&&log[log.length-1].includes('+1'));root.querySelector('.agent-world').innerHTML=`<div class="agent-room ${ended&&hidden==='L'?'revealed':''}"><span>L</span><strong>${ended?(hidden==='L'?'◆':'∅'):'?'}</strong><small>p = ${fmt(belief)}</small></div><div class="agent-core"><span class="eyebrow">AGENTE</span><div>◈</div><span>EPISODIO ${episode}</span></div><div class="agent-room ${ended&&hidden==='R'?'revealed':''}"><span>R</span><strong>${ended?(hidden==='R'?'◆':'∅'):'?'}</strong><small>p = ${fmt(1-belief)}</small></div>`;root.querySelector('.viz-stats').innerHTML=stat('H(CREENCIA)',fmt(H(belief)),C.c)+stat('LECTURAS',signals,C.o)+stat('PUNTAJE ACUMULADO',fmt(reward,1),C.g);root.querySelectorAll('[data-action]').forEach(b=>b.disabled=ended);root.querySelector('.agent-log').innerHTML=log.map(t=>`<div>${t}</div>`).join('')||'<div>Prior simétrico. La primera decisión es tuya.</div>';}
root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(ended)return;const action=b.dataset.action;if(action==='sense'){signals++;reward-=.1;const sign=Math.random()<.85?hidden:(hidden==='L'?'R':'L'),l=sign==='L'?.85:.15;belief=l*belief/(l*belief+(1-l)*(1-belief));log.push(`Señal ${sign} → p(L)=${fmt(belief)} · H=${fmt(H(belief))} nats`);}else{ended=true;const success=action===hidden;reward+=success?1:0;log.push(`Elegiste ${action}. Recurso en ${hidden}. ${success?'+1':'0'} puntos. Costo del episodio: ${fmt(signals*.1,1)}.`);}render()});root.querySelector('#anext').onclick=reset;render();}}
};
window.VISUALS=defs;window.MATH_ENGINE={entropy:H,kl:KL,gauss,clamp};
})();
